pub fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Preconditions from the problem:
    // - list is non-empty
    // - 1 <= k < n (so n >= 2)
    let n = list.len();
    let idx = k - 1; // convert 1-based k to 0-based index

    let mut out = Vec::with_capacity(n - 1);
    out.extend_from_slice(&list[..idx]);
    out.extend_from_slice(&list[idx + 1..]);
    out
}

